text:
{
  "components": [
    {
      "type": "claim",
      "quote": "L’énergie renouvelable excédentaire est stockée en été grâce à un procédé thermochimique, afin d’être utilisée en hiver.",
      "gist": "Excess renewable energy is stored in summer via a thermochemical process for winter use."
    },
    {
      "type": "entity",
      "quote": "soude caustique (hydroxyde de sodium)",
      "gist": "caustic soda (sodium hydroxide)"
    },
    {
      "type": "claim",
      "quote": "Cette dernière est chauffée en été avec de l’électricité ou de la chaleur renouvelable, l’eau s’évapore et la soude se concentre.",
      "gist": "The caustic soda is heated in summer with electricity or renewable heat, causing water to evaporate and the soda to concentrate."
    },
    {
      "type": "claim",
      "quote": "La soude caustique et l’eau peuvent être stockées à température ambiante jusqu’à l’hiver, sans perte.",
      "gist": "Caustic soda and water can be stored at room temperature until winter without loss."
    },
    {
      "type": "claim",
      "quote": "En diluant la soude caustique à nouveau par évaporation et absorption d'eau, de la chaleur se libère qui permet à la pompe à chaleur à réservoir à sorption de chauffer presque sans énergie électrique supplémentaire.",
      "gist": "By rediluting the caustic soda through evaporation and water absorption, heat is released to enable the sorption heat pump to heat with almost no additional electricity."
    }
  ]
}
